/* From Uiverse.io by vinodjangid07 - Tags: switch, toggle switch, metallic */
/* To hide the checkbox */
.__UIV_SCOPE__ #checkboxInput {
  display: none;
}

.__UIV_SCOPE__ .toggleSwitch {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 90px;
  height: 30px;
  background-color: rgb(206, 206, 206);
  border-radius: 40px;
  cursor: pointer;
  transition-duration: .3s;
}

.__UIV_SCOPE__ .toggleSwitch::after {
  content: "";
  position: absolute;
  height: 30px;
  width: 50%;
  left: 0px;
  background: conic-gradient(rgba(26, 26, 26, 0.555),white,rgba(26, 26, 26, 0.555),white,rgba(26, 26, 26, 0.555));
  border-radius: 40px;
  transition-duration: .3s;
  box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.281);
}

.__UIV_SCOPE__ #checkboxInput:checked+.toggleSwitch::after {
  transform: translateX(100%);
  transition-duration: .3s;
}
/* Switch background change */
.__UIV_SCOPE__ #checkboxInput:checked+.toggleSwitch {
  background-color: rgb(124, 173, 206);
  transition-duration: .3s;
}
